ctx.fillStyle = snakeColor;

snake.forEach((segment, index) => {
  const x = segment.x * gridSize;
  const y = segment.y * gridSize;
  ctx.beginPath();

  if (index === 0 || index === snake.length - 1) {
    ctx.roundRect(x, y, gridSize, gridSize, 3);
  } else {
